SELECT clock_timestamp() AS db_at,f.id,f.document_id,f.source_event_id,f.source_kind,f.operation_code,f.item_quantity,f.idempotency_key,f.created_at FROM operation_facts f WHERE f.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND f.seller_id='cf6d31c5-944b-4382-af34-636ca9aa8cc3' AND (f.document_id IN (SELECT o.id FROM fbs_orders o WHERE o.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND o.seller_id='cf6d31c5-944b-4382-af34-636ca9aa8cc3' AND o.supply_id='b82d1e9a-30d2-4d7b-b52d-9775c3d266e3' AND o.marketplace='ozon') OR f.source_event_id IN (SELECT o.id FROM fbs_orders o WHERE o.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND o.seller_id='cf6d31c5-944b-4382-af34-636ca9aa8cc3' AND o.supply_id='b82d1e9a-30d2-4d7b-b52d-9775c3d266e3' AND o.marketplace='ozon')) ORDER BY f.document_id,f.operation_code,f.created_at LIMIT 100
